CREATE OR REPLACE FUNCTION pg_temp.bl30_expand(template jsonb, source jsonb) RETURNS jsonb LANGUAGE plpgsql AS $expand$
DECLARE result jsonb;
BEGIN
  IF jsonb_typeof(template) = 'object' AND template ? '$from' THEN
    RETURN source #> ARRAY(SELECT jsonb_array_elements_text(template->'$from'));
  END IF;
  IF jsonb_typeof(template) = 'object' THEN
    SELECT COALESCE(jsonb_object_agg(k, pg_temp.bl30_expand(v,source)), '{}'::jsonb) INTO result FROM jsonb_each(template) a(k,v); RETURN result;
  END IF;
  IF jsonb_typeof(template) = 'array' THEN
    SELECT COALESCE(jsonb_agg(pg_temp.bl30_expand(v,source) ORDER BY n), '[]'::jsonb) INTO result FROM jsonb_array_elements(template) WITH ORDINALITY a(v,n); RETURN result;
  END IF;
  RETURN template;
END
$expand$;--> statement-breakpoint
