cation-place-washington-township:whitney-nicholas-j","before":null,"after":{"$from":["readModel","ballots","NJ:nj-2026-11-03","contacts","270"]}},{"key":"contact:ballot-nj-morris:wharton-borough-member-of-the-board-of-education-school-district-wharton-borough-school-district:rice-cristina","before":null,"after":{"$from":["readModel","ballots","NJ:nj-2026-11-03","contacts","271"]}},{"key":"contact:ballot-nj-morris:wharton-borough-member-of-the-board-of-education-school-district-wharton-borough-school-district:astrologo-anthony","before":null,"after":{"$from":["readModel","ballots","NJ:nj-2026-11-03","contacts","272"]}},{"key":"contact:ballot-nj-morris:wharton-borough-member-of-the-board-of-education-school-district-wharton-borough-school-district:gonzalez-gabriel","before":null,"after":{"$from":["readModel","ballots","NJ:nj-2026-11-03","contacts","273"]}},{"key":"contact:ballot-nj-morris:wharton-borough-member-of-the-board-of-education-unexpired-term-school-district-wharton-borough-school-district:pascale-colleen-f","before":null,"after":{"$from":["readModel","ballots","NJ:nj-2026-11-03","contacts","274"]}}],"changed":{"$from":["readModel","ballots","NJ:nj-2026-11-03","heldContests"]},"removed":{"$from":["readModel","ballots","NJ:nj-2026-11-03","heldContests"]},"held":{"$from":["readModel","ballots","NJ:nj-2026-11-03","heldContests"]}}},"receipt":{"contractVersion":2,"decision":"GOOD","candidateId":"official-ballot-authorities:ee731511c3b2bf79802880a92f3afbbf","sourceId":"official-ballot-authorities","recordClass":"BALLOT_CANDIDACY","scope":"US-NJ:state-election-ballots","validatedAt":"2026-10-15T18:48:55.858Z","checks":[{"check":"SOURCE_AUTHENTICITY","verdict":"PASS","code":"AUTHORITY_AND_RAW_PROVENANCE_VALID","detail":"Exact official election authorities in the saved-source receipt; https://www.morriscountyclerk.org/files/sharedassets/clerk/v/12/elections/past-results/2026-general-candidates.pdf; raw 55b1934a31b68d9b49f3cec0d5d87e4d62fc40bc15093d71015a96080b6ff597."},{"check":"SCHEMA_PARSE_VALIDITY","verdict":"PASS","code":"SCHEMA_AND_DISPOSITION_VALID","detail":"658/658 records normalized; 0 explicitly dropped."},{"check":"IDENTITY_JURISDICTION_VALIDITY","verdict":"PASS","code":"IDENTITY_AND_JURISDICTION_EXACT","detail":"374 exact identity binding(s); no name-only inheritance."},{"check":"TEMPORAL_VALIDITY","verdict":"PASS","code":"TEMPORAL_VERSION_VALID","detail":"2026-general; source through 2026-10-15T03:53:29.864Z."},{"check":"SEMANTIC_VALIDITY","verdict":"PASS","code":"FACT_INTERPRETATION_VALID","detail":"sourced official ballot contests and candidates."},{"check":"COMPLETENESS_HORIZON_VALIDITY","verdict":"PASS","code":"INDIVIDUAL_FACTS_NO_UNIVERSE_CLAIM","detail":"Valid individual facts may promote; broader completeness remains open."},{"check":"ABSENCE_VALIDITY","verdict":"PASS","code":"NO_ABSENCE_CLAIM","detail":"The projection makes no absence claim."},{"check":"DEPENDENT_READ_MODEL_VALIDITY","verdict":"PASS","code":"DEPENDENT_CONSUMERS_ACCEPT","detail":"generic state/election ballot Reader, lib/ballot/generic-projection.ts#readGenericBallotProjection (source-scoped pre-promotion)"}],"excludedFacts":{"$from":["readModel","ballots","NJ:nj-2026-11-03","heldContests"]}}},"seed":{"file":"data/ballot/2026-general/nj.json","fileSha":"84382e34f51862988db4a49d8a19b1ac81f515ba7df5c7997118fdc8456eb78f","promotedAt":"2026-10-15T18:48:55.858Z","events":[{"candidateId":"official-ballot-authorities:ee731511c3b2bf79802880a92f3afbbf","sequence":1,"state":"FETCHED","at":"2026-10-15T18:48:55.858Z","detail":"Acquired raw 55b1934a31b68d9b49f3cec0d5d87e4d62fc40bc15093d71015a96080b6ff597."},{"candidateId":"official-ballot-authorities:ee731511c3b2bf79802880a92f3afbbf","sequence":2,"state":"NORMALIZED","at":"2026-10-15T18:48:55.858Z","detail":"Normalized 658/658 records as fdac15d9f468db6962e58da1c6a2eed13eaad9b5e051d99027cffb461eb2a855."},{"candidateId":"official-ballot-authorities:ee731511c3b2bf79802880a92f3afbbf","sequence":3,"state":"VALIDATED","at":"2026-10-15T18:48:55.858Z","detail":"Every applicable GOOD check passed."},{"candidateId":"official-ballot-authorities:ee731511c3b2bf79802880a92f3afbbf","sequence":4,"state":"PROMOTED","at":"2026-10-15T18:48:55.858Z","detail":"Atomic pointer BALLOT_CANDIDACY:US-NJ:state-election-ballots moved from bootstrap/no-version to official-ballot-authorities:ee731511c3b2bf79802880a92f3afbbf."}]}}]$mappings$::jsonb) LOOP
    IF mapping ? 'seed' THEN
      expanded := pg_temp.bl30_expand(mapping->'template',mapping->'seedSource'); envelope := expanded->'candidate'; receipt := expanded->'receipt';
      at_time := (mapping->'seed'->>'promotedAt')::timestamptz;
    ELSE
      IF last_source IS DISTINCT FROM mapping->>'oldId' THEN
        SELECT * INTO prior FROM civic_data_promotions WHERE record_class=mapping->>'recordClass' AND scope=mapping->>'oldScope' FOR UPDATE;
        IF NOT FOUND THEN
          IF EXISTS (SELECT 1 FROM civic_data_candidates WHERE id=mapping->>'newId') THEN CONTINUE; END IF;
          RAISE EXCEPTION 'BL-30 source pointer missing: %', mapping->>'oldScope';
        END IF;
        SELECT * INTO STRICT held FROM civic_data_candidates WHERE id=prior.current_version_id;
        IF held.id IS DISTINCT FROM mapping->>'oldId' OR held.state <> 'PROMOTED' OR held.normalized_hash IS DISTINCT FROM mapping->>'oldHash'
          OR prior.payload IS DISTINCT FROM held.candidate->'readModel' OR prior.validation_receipt IS DISTINCT FROM held.validation_receipt
        THEN RAISE EXCEPTION 'BL-30 source authority changed: %', mapping->>'oldScope'; END IF;
        source := jsonb_build_object('candidate',held.candidate,'receipt',held.validation_receipt);
        last_source := held.id;
      END IF;
      expanded := pg_temp.bl30_expand(mapping->'template',source); envelope := expanded->'candidate'; receipt := expanded->'receipt'; at_time := prior.promoted_at;
    END IF;
    IF EXISTS (SELECT 1 FROM civic_data_promotions WHERE record_class=envelope->>'recordClass' AND scope=envelope->>'scope') THEN
      IF NOT EXISTS (SELECT 1 FROM civic_data_candidates WHERE id=envelope->>'id' AND candidate=envelope AND validation_receipt=receipt)
      THEN RAISE EXCEPTION 'BL-30 state authority conflicts: %', envelope->>'scope'; END IF;
      CONTINUE;
    END IF;
    INSERT INTO civic_data_candidates (id, source_id, record_class, scope, state, acquisition_succeeded,
      raw_hash, normalized_hash, retrieved_at, source_through, parser_version, identity, candidate,
      validation_receipt, promoted_version_id, last_known_good_version_id, failure_code, failure_detail)
    VALUES (envelope->>'id', envelope->>'sourceId', envelope->>'recordClass', envelope->>'scope', 'PROMOTED', true,
      envelope#>>'{retrieval,rawHash}', envelope#>>'{normalization,normalizedHash}', (envelope#>>'{retrieval,retrievedAt}')::timestamptz,
      envelope#>>'{temporal,sourceThrough}', envelope#>>'{normalization,parserVersion}', envelope->'identities', envelope,
      receipt, envelope->>'id', envelope->>'id', NULL, NULL);
    IF mapping ? 'seed' THEN
      FOR expanded IN SELECT value FROM jsonb_array_elements(mapping->'seed'->'events') LOOP
        IF (expanded->>'sequence')::integer > 4 THEN CONTINUE; END IF;
        INSERT INTO civic_data_candidate_events(candidate_id,sequence,state,at,detail)
        VALUES(envelope->>'id',(expanded->>'sequence')::integer,expanded->>'state',(expanded->>'at')::timestamptz,expanded->>'detail');
      END LOOP;
    ELSE
      FOR event IN SELECT * FROM civic_data_candidate_events WHERE candidate_id=held.id AND sequence<=4 ORDER BY sequence LOOP
        INSERT INTO civic_data_candidate_events(candidate_id,sequence,state,at,detail)
        VALUES(envelope->>'id',event.sequence,event.state,event.at,'BL-30 preserved state authority from ' || held.id || '.');
      END LOOP;
    END IF;
    INSERT INTO civic_data_promotions(key,source_id,record_class,scope,current_version_id,last_known_good_version_id,promoted_at,payload,validation_receipt)
    VALUES((envelope->>'recordClass')||':'||(envelope->>'scope'),envelope->>'sourceId',envelope->>'recordClass',envelope->>'scope',
      envelope->>'id',envelope->>'id',at_time,envelope->'readModel',receipt);
    IF NOT mapping ? 'seed' THEN
      copied_sequence := 4;
      FOR event IN SELECT * FROM civic_data_candidate_events WHERE candidate_id=held.id AND sequence>4 AND (
        left(detail,length('UNCHANGED_CONFIRMATION_V1 '))='UNCHANGED_CONFIRMATION_V1 '
        OR left(detail,length('UNCHANGED_CONFIRMATION_SOURCES_V1 '))='UNCHANGED_CONFIRMATION_SOURCES_V1 ') ORDER BY sequence LOOP
        prefix := CASE WHEN left(event.detail,length('UNCHANGED_CONFIRMATION_V1 '))='UNCHANGED_CONFIRMATION_V1 '
          THEN 'UNCHANGED_CONFIRMATION_V1 ' ELSE 'UNCHANGED_CONFIRMATION_SOURCES_V1 ' END;
        confirmation := substring(event.detail from length(prefix)+1)::jsonb || jsonb_build_object('versionId',envelope->>'id');
        IF prefix='UNCHANGED_CONFIRMATION_V1 ' THEN
          confirmation := confirmation || jsonb_build_object('scope',envelope->>'scope','pointerKey',(envelope->>'recordClass')||':'||(envelope->>'scope'),
            'readModelHash',envelope#>>'{normalization,normalizedHash}');
          IF confirmation#>'{retrieval,httpStatus}'='null'::jsonb THEN
            confirmation := jsonb_set(confirmation,'{retrieval,requestedUrl}',to_jsonb('derived:'||(envelope->>'sourceId')||':'||(envelope->>'scope')));
          END IF;
        END IF;
        copied_sequence := copied_sequence+1;
        INSERT INTO civic_data_candidate_events(candidate_id,sequence,state,at,detail)
        VALUES(envelope->>'id',copied_sequence,event.state,event.at,prefix||confirmation::text);
      END LOOP;
    END IF;
  END LOOP;
END
